import { UserType } from "@/types/services";
import { cookies as cookieStore } from "next/headers";
import prisma from "#/prisma/client";
import { User } from "@prisma/client";
import { Session } from "next-auth";
import { JWT, decode } from "next-auth/jwt";

// Generated by https://quicktype.io

export interface JWTDecodedType extends JWT {
  accessToken: string;
}

type SessionStorage = Session & {
  accessToken: unknown;
};
interface AuthServiceInterface {
  user?: UserType;
  session?: SessionStorage;
  oauthUser(body: {
    email: string;
    name: string;
    image: string;
  }): Promise<User>;
}

/** Authentication service
 * - [ ] Login
 * - [ ] Logout
 * - [ ] Register
 * - [ ] Forgot Password
 * - [ ] Create an Oauth2 User
 * - [ ] Check JWT Token
 * - [ ] Refresh JWT Token
 * - [ ] Revoke JWT Token
 */
class Auth implements AuthServiceInterface {
  user?: UserType;

  constructor(user?: UserType) {
    this.user = user;
  }

  prismaUser(email: string) {
    return prisma.user.findUnique({
      where: {
        email,
      },
    });
  }

  get cookieToken() {
    return cookieStore().get("next-auth.session-token");
  }

  private _getuserByEmail(email: string | null | undefined) {
    if (!email) return null;
    return prisma.user.findUnique({
      where: {
        email,
      },
    });
  }

  async decodedCookieData(): Promise<JWTDecodedType | null> {
    const token = this.cookieToken;
    if (!token) return null;

    const result = (await decode({
      token: token.value,
      secret: process.env.NEXTAUTH_SECRET,
    })) as JWTDecodedType;

    return result;
  }

  async login() {}

  async oauthUser(body: { email: string; name: string; image: string }) {
    const session = await this.decodedCookieData();
    const user = await this._getuserByEmail(session?.email);
    if (!user) {
      return await prisma.user.create({
        data: {
          email: body.email,
          name: body.name,
          image: body.image,
          type_account: "OAUTH",
        },
      });
    }

    return user;
  }
}

export default Auth;
